"""Turn the given HTTP request arguments from bytes to str.

    :param dict args: A dictionary of request arguments.
    :rtype: dict
    :returns: A dictionary of request arguments.
    """
def stringifyRequestArgs(args: Any) -> object {
    str_args = {};
    for (arg, values) in args.items() {
        arg = arg if isinstance(arg, str) else arg.decode("utf-8");
        values = [
            value.decode("utf-8") if isinstance(value, `bytes) else value
            for value in values
        ];
        str_args[arg] = values;
    }
    return str_args;
}

"""Convert pair of coordinates of a symmetric square array into consecutive index of
    flattened upper triangle. This is slimmed down so it won't throw errors like if i>n or
    j>n or if they're negative. Only checking for if the returned index is negative which
    could be problematic with wrapped indices.

    Parameters
    ----------
    n : int
        Dimension of square array
    i,j : int
        coordinates

    Returns
    -------
    int
    """
def sub_to_ind(n: Any, i: Any, j: Any) -> object {
    if (i < j) {
        k = 0;
        for l in range(1, (i + 2)) {
            k += n - l;
        }
        assert (k >= 0);
        return ((k - n) + j);
    } elif (i > j) {
        k = 0;
        for l in range(1, (j + 2)) {
            k += n - l;
        }
        assert (k >= 0);
        return ((k - n) + i);
    } else {
        raise Exception("Indices cannot be the same.");
    }
}

